                .orElseThrow(() -> new ErroNegocioException("FORMA_PAGAMENTO_INVALIDA"));
        if (!formaPagamento.parcelasValidas(parcelas)) {
            throw new ErroNegocioException("PARCELAMENTO_INVALIDO");
        }

